  and m.module_number = 5 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"industryStory":"Picture two teams with identical skill getting completely different results purely from how their objectives were framed. One is told to \"hit 90% coverage\"; it does, by carpeting the safe, easy code in tests, and its production incidents do not move. The other is told \"cut the incidents that reach customers in checkout\"; it writes fewer tests, but points every one at the risky flow, and the incident rate falls within a quarter. Same people, same tools — the objective decides where the effort lands, and the effort decides the outcome.","visualAid":{"type":"matrix","title":"Quality characteristics: where Northstar invests (illustrative, not universal)","colLabels":["Payments & billing","Public API","Marketing / web content"],"rowLabels":["Functional correctness","Reliability / availability","Performance","Security","Usability polish"],"cells":[[{"label":"Critical","level":"critical"},{"label":"High","level":"high"},{"label":"Low","level":"low"}],[{"label":"High","level":"high"},{"label":"Critical","level":"critical"},{"label":"Low","level":"low"}],[{"label":"Medium","level":"medium"},{"label":"High","level":"high"},{"label":"Low","level":"low"}],[{"label":"Critical","level":"critical"},{"label":"High","level":"high"},{"label":"Low","level":"low"}],[{"label":"Medium","level":"medium"},{"label":"Low","level":"low"},{"label":"Medium","level":"medium"}]]},"davidTip":"The interview question that separates senior QA leaders from senior testers is \"what are you trying to achieve, and how would you know?\" Testers answer with activity — \"run the regression, automate the smoke tests\". Leaders answer with outcomes and evidence — \"reduce customer-facing incidents in the highest-risk flow, measured by escaped defects and change failure rate, and here's the baseline I'd establish first.\" If your objectives cannot survive the follow-up \"and how would you know if it worked?\", they are not objectives yet — they are hopes with numbers attached.","badGood":{"label":"writing a quality objective","bad":"\"Improve overall product quality and increase test automation.\" — no outcome, no measure, no baseline, no trade-off; achievable in a report and meaningless in reality.","good":"\"Reduce escaped defects in payments and billing to near-zero this quarter (baseline established in week 1), driven by QA in refinement for all payment changes and contract tests at the billing boundary.\" — outcome, measure, baseline, and the leading activity that drives it."},"miniChallenge":"You have drafted five quality objectives for Northstar and they are all reasonable. Priya (VP Engineering) says she will only back three, because \"if everything's a priority, nothing is.\" In two or three sentences, decide which two you cut and how you justify the cut.","modelAnswer":"## Example\nI'd cut by business risk, not by how much I personally like each objective. If my five were payments defects, API reliability, regression speed, mobile polish and accessibility improvements, I'd keep the first three — they map straight onto Northstar's stated goals (fewer incidents, sellable SLAs, faster/cheaper delivery) — and cut mobile polish and accessibility this quarter, while stating plainly that \"cut\" means \"deliberately accepted as lower priority for now\", not \"ignored forever\". I'd tell Priya exactly that: \"These three protect the business goals you're measured on; the other two are real but they are next quarter's problem, and I'd rather do three things than fail at five.\" That gives her a defensible three and shows I can make the trade-off she's actually testing me on.","portfolioBuilder":"Add the **quality objectives** section to your QA Strategy v1: three to five objectives, each with its business line, its measure and baseline, and one leading activity. Put them on the one-page core — objectives are the part of a strategy people remember and repeat, so they earn their place on the front page, not the appendix.","resourcePreview":{"name":"Quality Objectives Worksheet","purpose":"A worksheet that turns vague aspirations into a small set of measurable quality objectives, each linked to a business goal, a measure, a baseline and a leading activity.","whenToUse":"Use it whenever you are asked to \"improve quality\" and need to convert that into objectives an exec would fund and a team can act on.","formats":["XLSX","PDF"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
